export type Atlas = {
  function: string; everyday: string[]; feel: string; skip: string; structure: string[];
  connections: { label: string; text: string; ids: string[] }[];
  fatigue: string[]; irritation: string[]; watch: string;
  practice: { name: string; cue: string; purpose: string }[];
  recovery: string[]; dosage: string; progress: string; sources: string[];
  nerve?: { roots: string; route: string; motor: string; sensory: string; branches: string[]; type: string };
};

type Detail = { action: string; attachment: string; nerves: string[]; joints: string[]; with: string[]; against: string[]; task: string; move: string; cue: string; recovery: string; note: string; source: string };
function d(action: string, attachment: string, nerves: string, joints: string, withIds: string, against: string, task: string, move: string, cue: string, recovery: string, note: string, source: string): Detail {
  const split = (x: string) => x ? x.split(',') : [];
  return { action, attachment, nerves: split(nerves), joints: split(joints), with: split(withIds), against: split(against), task, move, cue, recovery, note, source };
}
